import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static List<String> inputString = new ArrayList<>();
    static int currentLine = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append('\n');
        }
        String all = sb.toString().trim();
        if (!all.isEmpty()) {
            String[] parts = all.split("\n");
            for (String str : parts) {
                inputString.add(str.trim());
            }
        }
        run();
    }

    static String readLine() {
        return inputString.get(currentLine++);
    }

    static void run() {
        String[] tokens = readLine().split(" ");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        for (long i = n + 1; i <= m; i++) {
            if (isPrime(i) && i != m) {
                System.out.println("NO");
                return;
            }
            if (isPrime(i)) {
                if (i == m) {
                    System.out.println("YES");
                    return;
                }
            }
        }
        System.out.println("NO");
    }

    static boolean isPrime(long number) {
        if (number <= 1) {
            return false;
        }
        for (long i = 2; i < number; i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
}
